use rs_lvgl_ui::prelude::*;

struct Settings {
    enabled: bool,
    changes: u32,
}

#[derive(Clone)]
enum NotificationSettingsAction {
    Enabled(bool),
    Reset,
}

impl App for Settings {
    type Action = NotificationSettingsAction;

    fn update(&mut self, action: NotificationSettingsAction) {
        match action {
            NotificationSettingsAction::Enabled(value) => {
                self.enabled = value;
                self.changes += 1;
            }
            NotificationSettingsAction::Reset => {
                self.enabled = false;
                self.changes = 0;
            }
        }
    }

    fn view(&self, theme: &Theme) -> View<NotificationSettingsAction> {
        column([
            label("Notifications")
                .font(theme.title_font)
                .text_color(theme.text),
            row([
                switch(self.enabled)
                    .on_value_changed(|value| NotificationSettingsAction::Enabled(value != 0)),
                label(if self.enabled { "Enabled" } else { "Disabled" }),
            ])
            .style(Style::surface(theme))
            .gap(24),
            label(format!("Changed {} times", self.changes)),
            button("Reset")
                .on_click(NotificationSettingsAction::Reset)
                .style(Style::accent(theme)),
        ])
        .style(Style::screen(theme))
        .font(theme.body_font)
        .text_color(theme.text)
        .padding(32)
        .gap(24)
    }
}

fn app() -> impl App {
    Settings {
        enabled: false,
        changes: 0,
    }
}

event-map.excerpt:
//! Map direct/bubbled native events to queued messages.

use super::HandlerSlot;
use crate::events::value::read_value;
#[cfg(feature = "widget-textarea")]
use crate::events::value::with_text;
use crate::events::{map_event, InputEvent};
use rs_lvgl_sys::lv_obj_t;

impl<M: Clone + 'static> HandlerSlot<M> {
    pub(super) fn dispatch(
        &self,
        code: u32,
        target: *mut lv_obj_t,
        param: *mut cty::c_void,
        input: Option<InputEvent>,
        bubbled: bool,
    ) {
        // Collect before posting so handler execution cannot borrow the queue.
        let mut messages: [Option<M>; 6] = core::array::from_fn(|_| None);
        {
            let Ok(mut handlers) = self.handlers.try_borrow_mut() else {
                return;
            };
            if bubbled {
                if let (Some(map), Some(input)) = (&mut handlers.bubbled, &input) {
                    messages[0] = map(input);
                }
            } else {
                if code == rs_lvgl_sys::lv_event_code_t_LV_EVENT_CLICKED {
                    if let Some(msg) = &handlers.click {
                        messages[0] = Some(msg.clone());
                    }
                }
                if code == rs_lvgl_sys::lv_event_code_t_LV_EVENT_VALUE_CHANGED {
                    if let Some(map) = &mut handlers.value_changed {
                        messages[1] = read_value(target, self.value_source, param).and_then(map);
                    }
                    #[cfg(feature = "widget-textarea")]
                    if let Some(map) = &mut handlers.text_changed {
                        // SAFETY: the slot's value source was validated as a
                        // textarea. Copy before its native text can change.
                        messages[2] = unsafe { with_text(target, |text| map(text)) };
                    }
                }
                if let (Some(map), Some(event)) = (&mut handlers.event, map_event(code)) {
                    messages[3] = map(&event);
                }
                messages[4] = match input {
                    Some(InputEvent::Key(value)) => handlers.key.as_mut().map(|f| f(value)),
                    Some(InputEvent::Rotary(value)) => handlers.rotary.as_mut().map(|f| f(value)),
                    Some(InputEvent::Gesture(value)) => handlers.gesture.as_mut().map(|f| f(value)),
                    Some(InputEvent::Scroll(value)) => handlers.scroll.as_mut().map(|f| f(value)),
                    Some(InputEvent::Pointer(value)) => handlers.pointer.as_mut().map(|f| f(value)),
                    _ => None,
                };
                if code == rs_lvgl_sys::lv_event_code_t_LV_EVENT_LONG_PRESSED {
                    messages[5] = handlers.long_press.clone();
                }
            }
        }
        for message in messages.into_iter().flatten() {
            self.queue.post_event(message);
        }
    }
}

queue.excerpt:
/// Bounded message queue shared by the `Ui` and every mounted handler slot.
pub(crate) struct EventQueue<M> {
    pub(crate) diagnostics: crate::diagnostics::Diagnostics,
    items: RefCell<VecDeque<M>>,
    capacity: usize,
    dropped: Cell<u64>,
    stats: Cell<QueueStats>,
    event_policy: Cell<QueuePolicy<M>>,
    event_observer: RefCell<Option<Rc<dyn Fn(PostOutcome<M>)>>>,
}

impl<M> EventQueue<M> {
    pub(crate) fn new(capacity: usize) -> Self {
        Self {
            diagnostics: crate::diagnostics::Diagnostics::default(),
            items: RefCell::new(VecDeque::with_capacity(capacity)),
            capacity,
            dropped: Cell::new(0),
            stats: Cell::new(QueueStats::default()),
            event_policy: Cell::new(QueuePolicy::default()),
            event_observer: RefCell::new(None),
        }
    }

    pub(crate) fn post(&self, msg: M) {
        let _ = self.post_with(msg, QueuePolicy::default());
    }

    pub(crate) fn post_with(&self, msg: M, policy: QueuePolicy<M>) -> PostOutcome<M> {
        let mut items = self.items.borrow_mut();
        let mut stats = self.stats.get();
        if let (Some(merge), Some(tail)) = (policy.merge, items.back_mut()) {
            if let Some(merged) = merge(tail, &msg) {
                *tail = merged;
                stats.merged += 1;
                self.stats.set(stats);
                return PostOutcome::Merged;
            }
        }
        if items.len() == self.capacity {
            if policy.overflow == QueueOverflow::RejectNew {
                stats.rejected += 1;
                self.stats.set(stats);
                return PostOutcome::Rejected(msg);
            }
            let evicted = items.pop_front().expect("full nonempty queue");
            self.dropped.set(self.dropped.get() + 1);
            stats.evicted += 1;
            self.stats.set(stats);

